<?php require __DIR__.'/../app/bootstrap.php';$u=require_admin();$title='Seller applications';$filter=param('status');$where=in_array($filter,['pending','approved','rejected'])?' WHERE s.status=?':'';$applications=all('SELECT s.*,u.full_name,u.email FROM seller_applications s JOIN users u ON u.id=s.user_id'.$where.' ORDER BY s.submitted_at DESC',$where?[$filter]:[]);require ROOT.'/app/workspace-start.php'; ?>
<div class="dash-header"><div><h1>Seller applications</h1><p class="dash-sub">Meet the people behind the next great kitchen.</p></div></div><nav class="tabs" aria-label="Application status"><?php foreach([''=>'All','pending'=>'Pending','approved'=>'Approved','rejected'=>'Rejected'] as $key=>$label): ?><a class="pill <?=$filter===$key?'primary':''?>" href="?status=<?=e($key)?>"><?=e($label)?></a><?php endforeach ?></nav><section class="panel"><?php if(!$applications): ?><p class="empty">No applications in this view.</p><?php else: ?><div class="table-wrap"><table><thead><tr><th>Business</th><th>Owner / email</th><th>Status</th><th>Submitted</th><th>Action</th></tr></thead><tbody><?php foreach($applications as $a): ?><tr><td><?=e($a['business_name'])?></td><td><?=e($a['full_name'])?><br><small><?=e($a['email'])?></small></td><td><span class="chip <?=$a['status']==='pending'?'pending':''?>"><?=e(ucfirst($a['status']))?></span></td><td><?=e(local_time($a['submitted_at']))?></td><td><a class="pill compact" href="<?=e(url('admin/application.php?id='.$a['id']))?>">View application →</a></td></tr><?php endforeach ?></tbody></table></div><?php endif ?></section><?php require ROOT.'/app/workspace-end.php'; ?>
